from pathlib import Path
from html import escape
r=Path(__file__).resolve().parent
styles='''*{box-sizing:border-box}body{margin:0;background:#070c18;color:#f5f8ff;font-family:Manrope,system-ui,sans-serif;line-height:1.65}main{max-width:1320px;margin:auto;padding:clamp(20px,5vw,70px)}h1,h2{font-family:Barlow,system-ui,sans-serif;line-height:1.05}h1{font-size:clamp(52px,9vw,110px);margin:20px 0}h2{font-size:clamp(40px,6vw,72px);margin:20px 0}p{max-width:800px;color:#bac9df}a{color:var(--accent,#ff4f66);text-underline-offset:5px}header,section{padding:35px 0 55px;border-bottom:1px solid #33415a}.eyebrow{color:var(--accent,#ff4f66);font-size:12px;letter-spacing:.2em}.hero{display:block;width:100%;max-height:480px;object-fit:cover;border-radius:26px;margin:24px 0}.actions{display:flex;gap:12px;flex-wrap:wrap;margin:24px 0}.actions a{border:1px solid #4d6384;border-radius:14px;padding:12px 18px;text-decoration:none}.actions a:focus-visible{outline:3px solid #82b9ff;outline-offset:4px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px;margin-top:30px}.grid img{width:100%;height:auto;border-radius:20px;border:1px solid #33415a}figure{margin:0}figcaption{font-size:12px;color:#bac9df;padding-top:10px}footer{padding-top:35px;color:#bac9df}#midnight-express{--accent:#ffc778}#midnight-express h2{font-family:Rajdhani,sans-serif}#astral-tide{--accent:#a0e8d5}#astral-tide h2{font-family:SpaceGrotesk,sans-serif}.playful{--accent:#ffe18a}.playful h2{font-family:Fredoka,sans-serif}.halloween{--accent:#ffc17a}.halloween h2{font-family:Grenze,serif}.icons{display:flex;gap:18px;align-items:center}.icons img{width:88px;border-radius:20px}@media(max-width:900px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:520px){.grid{grid-template-columns:1fr}figure{max-width:380px;margin:auto}}'''
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Veyra · Theme Studio</title><style>
@font-face{font-family:Rajdhani;src:url(midnight-express/fonts/Rajdhani.ttf);font-weight:700}
@font-face{font-family:SpaceGrotesk;src:url(astral-tide/fonts/SpaceGrotesk.ttf);font-weight:700}
@font-face{font-family:Fredoka;src:url(playtime-club/fonts/Fredoka.ttf);font-weight:700}
@font-face{font-family:Manrope;src:url(halloween-nocturne/fonts/Manrope.ttf)}
@font-face{font-family:Barlow;src:url(web-slinger/fonts/BarlowCondensed.ttf);font-weight:700}
@font-face{font-family:Grenze;src:url(halloween-nocturne/fonts/GrenzeGotisch.ttf);font-weight:700}
'''+styles+'''</style></head><body><main><header><div class="eyebrow">VEYRA / THEME STUDIO</div><h1>Five worlds.<br>One Veyra.</h1><p>Night journeys, oceanic wonder, cartoon fan artwork, matching branding and native controls. Made by Bhavishya Dalal for preview 0.1.7-beta1 / code 25.</p><p>These are native component studies in illustrative layouts, not full Android device screenshots. Music artwork shown here is demonstration art.</p><nav class="actions"><a href="#midnight-express">Midnight Express</a><a href="#astral-tide">Astral Tide</a><a href="#playtime-club">Playtime Club</a><a href="#web-slinger">Web Slinger</a><a href="#halloween-nocturne">Halloween Nocturne</a><a href="README.md">Installation and compatibility</a></nav></header>'''
labels={'home':'Home / real shared Veyra branding and artwork frames','home-large-text':'Home / 320 dp / 150% text','player':'Player / native controls and themed timeline','settings':'Settings / native row components','settings-large-text':'Settings / 320 dp / 150% text','actions':'Actions / shared backgrounds and icon housings, illustrative rows','actions-large-text':'Actions / 320 dp / 150% text','studio':'Theme Studio / compact native collection rows','studio-large-text':'Theme Studio / 320 dp / 150% text','icons':'Icon chooser / grouped native selection tiles','icons-large-text':'Icon chooser / 320 dp / 150% text'}
for id,name,version,folder,description in [('midnight-express','Midnight Express',1,'previews/midnight-express','Rain on the window. Amber in the carriage. Your next stop, another song.'),('astral-tide','Astral Tide',1,'previews/astral-tide','Bioluminescent ocean. Sea-glass mint. Drift deeper, hear everything.'),('playtime-club','Playtime Club',1,'previews/playtime-club','Cartoon joy. Puffy controls. A little joy, every play.'),('web-slinger','Web Slinger',1,'previews/web-slinger','Crimson glass. Cobalt webs. Your city, your soundtrack.'),('halloween-nocturne','Halloween Nocturne',3,'previews','Smoked glass. Pumpkin amber. A different kind of night.')]:
 html+=f'<section id="{id}" class="{ "playful" if id=="playtime-club" else "halloween" if version==3 else "web" }"><div class="eyebrow">{escape(name.upper())} / V{version}</div><h2>{name}</h2><p>{description}</p><img class="hero" src="{id}/artwork/header.webp" alt="{name} theme artwork"><div class="icons"><img src="{id}/artwork/brand.webp" alt="Matching Veyra icon"><p>Matching in-app branding and an optional bundled Android launcher icon. Opt into the matching launcher during Apply, or choose it in the grouped icon picker.</p></div><nav class="actions"><a href="packs/{id}-v{version}.zip" download>Download theme ZIP</a><a href="packs/{id}-v{version}.zip.sha256">SHA-256 checksum</a></nav><div class="grid">'
 for key,label in labels.items():
  if id in {"astral-tide","midnight-express"} and key not in {"home","home-large-text","player","studio","studio-large-text","settings"}:continue
  if id=="playtime-club" and key not in {"home","home-large-text","player","studio","studio-large-text","settings","actions"}:continue
  html+=f'<figure><a href="{folder}/{key}.png"><img src="{folder}/{key}.png" alt="{escape(name+" · "+label)}"></a><figcaption>{escape(label)}</figcaption></figure>'
 html+='</div></section>'
html+='''<footer>Apply through Settings → Appearance → Theme studio in the latest preview. Theme ZIPs are not APKs. Stable 0.1.6 is unchanged.<p>Unofficial cartoon fan artwork: character rights remain with their respective owners; see README and the pack artwork notice. No endorsement. Original Veyra glyphs and waveform icon · Rajdhani, Space Grotesk, Fredoka, Manrope, Barlow Condensed and Grenze Gotisch retain their included SIL Open Font Licenses.</p></footer></main></body></html>'''
(r/'index.html').write_text(html)
